// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.File;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * LMDB end-to-end guards for the standard {@code FilterOptimizer} relocation rule. The LMDB pipeline runs
 * {@code FilterOptimizer(null, false, false)} before its own rewrites, and a filter mis-placed onto a LeftJoin is then
 * amplified by the null-rejecting OPTIONAL rewrite into an inner join, so the store-level result must be checked too.
 */
public class LmdbFilterRelocationSoundnessTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\n";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n" + trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	private static StringBuilder filler(String predicate, int count) {
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < count; i++) {
			sb.append(":f").append(i).append(' ').append(predicate).append(" :fv").append(i).append(" .\n");
		}
		return sb;
	}

	@Test
	public void filterIsNotPushedOntoLeftJoinWhenSiblingBindsTheOptionalVariable() throws Exception {
		load(":s1 :p :v . :s1 :r :v .\n" + filler(":r", 200));
		String query = "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x FILTER(?x = ?y) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/v"), rows(query, "s", "x", "y"));
	}

	@Test
	public void filterIsNotPushedOntoLeftJoinWhenSiblingBindsTheOptionalVariableWideJoin() throws Exception {
		StringBuilder data = new StringBuilder(":s1 :p :v . :s1 :r :v .\n:s2 :p :v . :s2 :q :w . :s2 :r :v .\n");
		StringBuilder patterns = new StringBuilder();
		for (int i = 0; i < 18; i++) {
			patterns.append(" ?s :f").append(i).append(" ?w").append(i).append(" .");
			data.append(":s1 :f").append(i).append(" :v").append(i).append(" .\n");
			data.append(":s2 :f").append(i).append(" :v").append(i).append(" .\n");
		}
		load(data.toString());
		String query = "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x ." + patterns
				+ " FILTER(?x = ?y) }";
		// s2's OPTIONAL binds ?x = :w which is incompatible with ?s :r :v, so only s1 survives
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/v"), rows(query, "s", "x", "y"));
	}

	@Test
	public void filterIsNotPushedIntoOuterLeftJoinWhenBothOptionalsBindTheVariable() throws Exception {
		load(":s1 :p :o1 . :s1 :r :v .\n" + ":s2 :p :o2 . :s2 :q :v .\n" + ":s3 :p :o3 . :s3 :q :w . :s3 :r :v .\n");
		String query = "SELECT ?s ?x WHERE { ?s :p ?o OPTIONAL { ?s :q ?x } OPTIONAL { ?s :r ?x } FILTER(?x = :v) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v", "s=http://ex/s2 x=http://ex/v"), rows(query, "s", "x"));
	}

	@Test
	public void filterOnOptionalOnlyVariableStillFiltersCorrectly() throws Exception {
		load(":s1 :p :o . :s1 :q :v . :s1 :r :a .\n:s2 :p :o . :s2 :q :w . :s2 :r :b .\n:s3 :p :o . :s3 :r :c .\n");
		String query = "SELECT ?s ?x ?z WHERE { ?s :p ?o OPTIONAL { ?s :q ?x } ?s :r ?z FILTER(?x = :v) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v z=http://ex/a"), rows(query, "s", "x", "z"));
	}
}
